    return _as_field(values, label="poisson")


def hydraulic_conductance(values: Iterable[float]) -> ThroatField:
    """Reduced stand-in for a hydraulic conductance model."""

    return _as_field(values, label="hydraulic")


def taylor_aris_diffusion(values: Iterable[float]) -> ThroatField:
    """Reduced stand-in for a Taylor-Aris diffusion conductance model."""

    return _as_field(values, label="taylor_aris")


def diffusive_migrative_conductance(values: Iterable[float]) -> ThroatField:
    """Reduced stand-in for a coupled diffusion-migration model."""

    return _as_component_field(values, label="diffusive_migrative")


def electrochemical_coupled_conductance(values: Iterable[float]) -> ThroatField:
    """Reduced stand-in for a second coupled transport model."""

    return _as_component_field(values, label="electrochemical_coupled")


def ad_dif_conductance(gh: np.ndarray, pressure_drop: np.ndarray) -> np.ndarray:
    """Compute the reduced advection-diffusion contribution for a throat field."""

    gh = np.asarray(gh, dtype=float)
    qij = -gh * np.diff(pressure_drop, axis=1).squeeze()
    return np.append(qij, -qij)


